        run.job_id = Some(self.job_id.clone());
        self.log.start(role, run, tag);
    }

    /// The run ID the log is kept under (the job ID when the initiator sent
    /// none).
    pub(crate) fn run_id(&self) -> String {
        self.log.run_id()
