use blit_core::admin::jobs::WatchSnapshot;
use blit_core::copy::{open_to_write, Within};
use blit_core::job_log::{self, Event, EventBody, LogKey, LogLine, Outcome, Role, RunInfo, RunStart, Summary};
use blit_core::job_record::{settle, DaemonAnswer, JobSpec, LogRead, RunRecord, RunState, SpecEndpoint};
use blit_core::remote::transfer::progress::AUDIT_LANE_DEPTH;
use blit_core::remote::transfer::RemoteTransferProgress;
use blit_core::run_log::{End, LogPlace, RunLog, RunTotals};
use std::{fs, path::PathBuf};

fn read_session(run: &str, outcome: Outcome) -> LogRead {
    let key = LogKey::new("asked", "daemon", Role::Destination, 1).unwrap();
    let mut read = LogRead::default();
    read.begin_log(Some(key));
    let bodies = [
        EventBody::RunStart(Box::new(RunStart {
            format: job_log::FORMAT.into(), version: job_log::VERSION,
            run_id: run.into(), participant: "daemon".into(), role: Role::Destination,
            attempt: 1, host: String::new(), build: String::new(), run: RunInfo::default(),
        })),
        EventBody::Summary(Summary { all_events_logged: true, ..Summary::default() }),
        EventBody::RunEnd { outcome, detail: None },
    ];
    for (i, body) in bodies.into_iter().enumerate() {
        read.read_line(LogLine::Event(Event { seq: i as u64, ts_ms: 1, body }));
    }
    read.end_log();
    read
}

fn inspect_readers() {
    let endpoint = SpecEndpoint::Local { path: "/example".into() };
    let spec = JobSpec::new("m1", "copy", "/".into(), endpoint.clone(), endpoint, Default::default(), None);
    let mut waiting = RunRecord::starting("asked", &spec);
    waiting.state = RunState::Waiting { daemon: "server:9031".into(), job_id: "t1-0".into() };
    let foreign = read_session("different", Outcome::Ok);
    assert!(!foreign.complete());
    match settle(&waiting, &foreign, Some(&WatchSnapshot::NotFound)) {
        Ok(DaemonAnswer::Ended(r)) => println!("foreign_log complete={} settled_as={:?} truncated={}", foreign.complete(), r.outcome, r.failures_truncated),
        x => println!("foreign_log other_result={x:?}"),
    }
    let mut closed = read_session("asked", Outcome::Ok);
    assert!(closed.complete());
    closed.read_line(LogLine::Event(Event { seq: 3, ts_ms: 2, body: EventBody::FileFailed {
        path: "after-end".into(), raw: None, reason: "test".into(), left_in_place: Some(false),
    }}));
    println!("outside_session complete={} recorded_failures={}", closed.complete(), closed.failures.len());
}

async fn inspect_writer() {
    let dir = tempfile::tempdir().unwrap();
    let log = RunLog::new(Some(LogPlace { dir: dir.path().into(), participant: "writer".into(), keep: 4, finished: None }), "early");
    let sender = RemoteTransferProgress::audit_only(log.audit_lane_at(End::Receiving).unwrap());
    // More than fits in the queue, so an accepted event must reach the relay before start.
    let sent = AUDIT_LANE_DEPTH + 1;
    for n in 0..sent {
        sender.report_file_failed(format!("file{n}"), "test".into()).await;
    }
    drop(sender);
    log.start(Role::Destination, RunInfo::default(), None);
    let report = log.close(Outcome::Failed, None, Some(RunTotals { files_failed: sent as u64, failed_paths_truncated: true, ..Default::default() })).await.unwrap();
    let mut failures = 0;
    let mut evidence = None;
    for line in job_log::open_log(&report.path.unwrap()).unwrap() {
        if let LogLine::Event(event) = line.unwrap() {
            match event.body {
                EventBody::FileFailed { .. } => failures += 1,
                EventBody::Summary(summary) => evidence = Some(summary.all_events_logged),
                _ => {}
            }
        }
    }
    println!("prestart_lane accepted={sent} recorded={failures} all_events_logged={evidence:?} report_complete={}", report.complete);
}

fn inspect_aliases() {
    use std::os::unix::fs::symlink;
    let dir = tempfile::tempdir().unwrap();
    let root = dir.path().join("dst");
    fs::create_dir(&root).unwrap();
    let within = Within::hold(&root);
    let name = "d".repeat(200);
    let half: PathBuf = (0..11).map(|_| &name).collect();
    let middle = root.join(&half);
    fs::create_dir_all(&middle).unwrap();
    let alias = dir.path().join("short");
    symlink(&middle, &alias).unwrap();
    let rest = alias.join(&half);
    fs::create_dir_all(&rest).unwrap();
    let leaf = rest.join("leaf");
    fs::write(&leaf, b"ok").unwrap();
    let entry = root.join("entry");
    symlink(&leaf, &entry).unwrap();
    let sys = fs::OpenOptions::new().write(true).open(&entry);
    let blit = open_to_write(&entry, Some(&within), false);
    println!("long_alias kernel_error={:?} blit_error={:?} contents={:?}", sys.err(), blit.err(), fs::read(&entry).unwrap());
    let missing = dir.path().join("missing_alias");
    symlink(root.join("absent/."), &missing).unwrap();
    let entry = root.join("missing_entry");
    symlink(&missing, &entry).unwrap();
    println!("missing_slashdot kernel_error={:?} blit_error={:?}", fs::metadata(&entry).unwrap_err().raw_os_error(), open_to_write(&entry, Some(&within), false).unwrap_err().raw_os_error());
}

#[tokio::main(flavor = "current_thread")]
async fn main() {
    inspect_readers();
    inspect_aliases();
    inspect_writer().await;
}
