use blit_core::{job_log::RunTag, run_log::LogReport as Unused};
'@ | Out-Null
@'
async fn inspect_restart() {
    let dir = tempfile::tempdir().unwrap();
    let place = LogPlace { dir: dir.path().into(), participant: "daemon".into(), keep: 8, finished: None };
    let run = RunLog::new(Some(place.clone()), "first");
    run.start(Role::Destination, RunInfo::default(), None);
    let held = run.audit_lane().unwrap();
    let mut pending = Box::pin(run.close(Outcome::Failed, Some("first close".into()), Some(RunTotals::default())));
    tokio::select! {
        biased;
        _ = &mut pending => panic!("close completed with a held sender"),
        _ = std::future::ready(()) => {}
    }
    drop(held);
    let first = run.close(Outcome::Ok, None, Some(RunTotals::default())).await.unwrap();
    assert!(first.complete);
    let second_tag = Some(job_log::RunTag { run_id: "second".into(), attempt: 1 });
    run.start(Role::Destination, RunInfo::default(), second_tag);
    let late = pending.await;
    let second = run.close(Outcome::Ok, None, Some(RunTotals::default())).await;
    let mut observed_end = None;
    if let Some(path) = late.as_ref().and_then(|r| r.path.as_ref()) {
        for line in job_log::open_log(path).unwrap() {
            if let LogLine::Event(Event {body: EventBody::RunEnd {outcome,..},..}) = line.unwrap() {
                observed_end = Some(outcome);
            }
        }
    }
    println!("old_close filename={:?} recorded_outcome={observed_end:?} second_close_had_writer={}", late.as_ref().and_then(|r|r.path.as_ref()).and_then(|p| p.file_name()), second.is_some());

    let cut = RunLog::new(Some(place), "abandoned");
    cut.start(Role::Destination, RunInfo::default(), None);
    let held = cut.audit_lane().unwrap();
    tokio::time::pause();
    let first = cut.close(Outcome::Failed, None, Some(RunTotals::default())).await.unwrap();
    assert!(!first.complete);
    drop(held);
    cut.start(Role::Destination, RunInfo::default(), Some(job_log::RunTag {run_id:"clean".into(),attempt:1}));
    let fresh = RemoteTransferProgress::audit_only(cut.audit_lane().unwrap());
    fresh.report_file_failed("only_file".into(), "test".into()).await;
    drop(fresh);
    let second = cut.close(Outcome::Failed, None, Some(RunTotals::default())).await.unwrap();
    let counts = job_log::open_log(second.path.as_ref().unwrap()).unwrap()
        .filter(|line| matches!(line, Ok(LogLine::Event(Event {body:EventBody::FileFailed {..},..})))).count();
    println!("restart_after_cut failures_sent=1 failures_recorded={counts} report_complete={}", second.complete);
}
